        max: Optional['types.VocabularyMaxAggregateInput'] = None,
        having: Optional['types.VocabularyScalarWhereWithAggregatesInput'] = None,
        count: Optional[Union[bool, 'types.VocabularyCountAggregateInput']] = None,
